// @FIGURE_CODE_BEGIN
var FONT = 'Georgia, "Times New Roman", serif';
var TEAL = '#9ed8cd', OUTLINE = '#2b2b2b', ORANGE = '#d9805c', HOT = '#ef6c2a', DIM = '#d8d3cf', INK = '#111111';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 760, 490);

var gPaths = draw.group();
var gDash = draw.group();
var gBoxes = draw.group();
var gLabels = draw.group();

/* ---------- math text helpers ---------- */
function parseMath(str) {
  var parts = [], buf = '', i = 0;
  function flush() { if (buf) { parts.push({ s: buf, sub: false }); buf = ''; } }
  while (i < str.length) {
    var c = str.charAt(i);
    if (c === '_') {
      flush(); i++;
      if (str.charAt(i) === '{') {
        var j = str.indexOf('}', i);
        parts.push({ s: str.slice(i + 1, j), sub: true });
        i = j + 1;
      } else { parts.push({ s: str.charAt(i), sub: true }); i++; }
    } else { buf += c; i++; }
  }
  flush();
  return parts;
}

function mathText(parent, x, y, str, size, opts) {
  opts = opts || {};
  var parts = parseMath(str);
  var offset = 0;
  var t = parent.text(function (add) {
    parts.forEach(function (p) {
      var sz = p.sub ? size * 0.68 : size;
      var tgt = p.sub ? size * 0.26 : 0;
      var ts = add.tspan(p.s);
      ts.font({ size: sz, family: FONT, style: (opts.italic === false ? 'normal' : 'italic') });
      ts.dy(tgt - offset);
      offset = tgt;
    });
  });
  t.font({ family: FONT, size: size });
  t.attr({ x: x, y: y, 'text-anchor': opts.anchor || 'start', fill: opts.color || INK });
  return t;
}

/* segs: [{t:'Policy', italic:false, gap:7}, {t:'\u03C0[a_t|s_t]'}] */
function labelBlock(parent, cx, baseY, segs, size, opts) {
  opts = opts || {};
  var g = parent.group();
  var texts = [];
  var xcur = 0;
  segs.forEach(function (s) {
    var el = mathText(g, xcur, 0, s.t, size, { italic: s.italic, anchor: 'start', color: opts.color });
    texts.push(el);
    xcur += el.bbox().width + (s.gap || 0);
  });
  var bb = g.bbox();
  if (opts.chip) {
    var r = g.rect(bb.width + 10, bb.height + 3).move(bb.x - 5, bb.y - 1.5).fill('#ffffff');
    r.back();
    g.chip = r;
  }
  var dx = (opts.align === 'left') ? (cx - bb.x) : (cx - (bb.x + bb.width / 2));
  g.translate(dx, baseY);
  g.texts = texts;
  return g;
}

function emphasize(g, on) {
  if (!g || !g.texts) return;
  g.texts.forEach(function (t) {
    t.font({ weight: on ? 'bold' : 'normal' });
    t.attr('fill', on ? '#0a3f36' : INK);
  });
}

/* ---------- orange connector paths ---------- */
var PATHS = {};
function mkPath(id, pts, opts) {
  opts = opts || {};
  var g = gPaths.group();
  var str = pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
  var line = g.polyline(str).fill('none').stroke({ color: ORANGE, width: 2.6, linecap: 'round', linejoin: 'round' });
  var head = null;
  if (opts.head !== false) {
    var n = pts.length, a = pts[n - 2], b = pts[n - 1];
    var dx = b[0] - a[0], dy = b[1] - a[1], L = Math.sqrt(dx * dx + dy * dy);
    var ux = dx / L, uy = dy / L, px = -uy, py = ux, l = 13, w = 7;
    var hp = [[b[0], b[1]],
    [b[0] - ux * l + px * w, b[1] - uy * l + py * w],
    [b[0] - ux * l - px * w, b[1] - uy * l - py * w]];
    head = g.polygon(hp.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(ORANGE).stroke('none');
  }
  var hit = g.polyline(str).fill('none').stroke({ color: '#000', width: 18, opacity: 0 });
  hit.attr('pointer-events', 'stroke').css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(opts.tip || '', e); });
  hit.on('mouseleave', function () { hideTooltip(); });
  hit.on('click', function () { showPopup(opts.popTitle || 'Signal', opts.pop || ''); });

  var obj = {
    set: function (mode) {
      var c = mode === 'hot' ? HOT : (mode === 'dim' ? DIM : ORANGE);
      var w = mode === 'hot' ? 4.4 : (mode === 'dim' ? 2 : 2.6);
      line.stroke({ color: c, width: w });
      if (head) head.fill(c);
    }
  };
  PATHS[id] = obj;
  return obj;
}

