/* ---------- state machine ---------- */
var state = { phase: 'idle', timeShift: true, focus: null };

var PHASES = {
  idle: { hot: [], normal: [], dimRest: false, box: null, bold: [] },
  observe: { hot: ['sUp', 'rUp'], normal: [], dimRest: true, box: 'agent', bold: [] },
  act: { hot: ['act'], normal: ['sUp'], dimRest: true, box: 'agent', bold: ['policy'] },
  respond: { hot: ['sOut', 'rOut'], normal: ['act', 'sBus'], dimRest: true, box: 'env', bold: ['env'] },
  advance: { hot: ['sOut', 'rOut', 'sUp', 'rUp'], normal: [], dimRest: true, box: null, bold: [] }
};

function render() {
  var spec = PHASES[state.phase] || PHASES.idle;
  var hot = spec.hot.slice(), normal = spec.normal.slice(), dimRest = spec.dimRest;
  var boxFocus = spec.box, bold = spec.bold.slice();

  if (state.focus === 'agent') { hot = ['act']; normal = []; dimRest = true; boxFocus = 'agent'; bold = ['policy']; }
  if (state.focus === 'env') { hot = ['sOut', 'rOut']; normal = []; dimRest = true; boxFocus = 'env'; bold = ['env']; }

  Object.keys(PATHS).forEach(function (k) {
    var mode = (hot.indexOf(k) >= 0) ? 'hot' : (normal.indexOf(k) >= 0 ? 'normal' : (dimRest ? 'dim' : 'normal'));
    PATHS[k].set(mode);
  });

  agentBox.halo.animate(200).attr('opacity', boxFocus === 'agent' ? 0.9 : 0);
  envBox.halo.animate(200).attr('opacity', boxFocus === 'env' ? 0.9 : 0);

  emphasize(policyG, bold.indexOf('policy') >= 0);
  var envBold = bold.indexOf('env') >= 0;
  emphasize(transG, envBold); emphasize(transF, envBold);
  emphasize(rewG, envBold); emphasize(rewF, envBold);

  var showDash = state.timeShift;
  dashLine.attr('opacity', showDash ? 1 : 0);
  dashLab1.attr('opacity', showDash ? 1 : 0);
  dashLab2.attr('opacity', showDash ? 1 : 0);

  var crossing = (state.phase === 'advance' && !state.focus);
  dashLine.stroke({ width: crossing ? 6.5 : 4.5 });
  if (dashLab1.chip) dashLab1.chip.fill(crossing ? '#ffe6a8' : '#ffffff');
  if (dashLab2.chip) dashLab2.chip.fill(crossing ? '#ffe6a8' : '#ffffff');
}

/* ---------- interactions ---------- */
