});

function update_phase(v) { stopPlay(); state.phase = v; state.focus = null; render(); }
function toggle_timeShift(on) { state.timeShift = on; render(); }

/* playback */
var playTimer = null;
var cycle = ['observe', 'act', 'respond', 'advance'];
var cycleIdx = 0;
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  var b = document.getElementById('playBtn');
  if (b) b.textContent = '\u25B6 Play one MDP time step';
}
function trigger_stepCycle() {
  if (playTimer) { stopPlay(); return; }
  var b = document.getElementById('playBtn');
  b.textContent = '\u23F8 Pause loop';
  cycleIdx = 0;
  state.focus = null;
  tick();
  playTimer = setInterval(tick, 1500);
  function tick() {
    var p = cycle[cycleIdx % cycle.length];
    cycleIdx++;
    state.phase = p;
    document.getElementById('phaseInput').value = p;
    render();
  }
}

/* ---------- demo steps ---------- */
var steps = [
  { title: 'The closed loop', narration: 'Two components only: an Agent holding a policy, and an Environment holding a state-transition and a reward distribution. Every orange arrow is information passing between them.', state: { phase: 'idle', timeShift: true } },
  { title: 'Agent observes s\u209C and r\u209C', narration: 'The environment\u2019s last outputs arrive at the agent as the current state s\u209C and reward r\u209C \u2014 these are the agent\u2019s only inputs.', state: { phase: 'observe', timeShift: true } },
  { title: 'Policy chooses a\u209C', narration: 'The policy \u03C0[a\u209C|s\u209C] maps the observed state to an action a\u209C, which travels around the right side into the environment.', state: { phase: 'act', timeShift: true } },
  { title: 'Environment responds', narration: 'Given s\u209C and a\u209C, the environment samples the next state from Pr(s\u209C\u208A\u2081|s\u209C,a\u209C) and the reward from Pr(r\u209C\u208A\u2081|s\u209C,a\u209C) \u2014 both outputs depend only on the current state and action, which is the Markov property.', state: { phase: 'respond', timeShift: true } },
  { title: 'Time advances', narration: 'Crossing the dashed line, s\u209C\u208A\u2081 and r\u209C\u208A\u2081 become s\u209C and r\u209C for the next tick, and the identical cycle repeats forever.', state: { phase: 'advance', timeShift: true } },
  { title: 'Hide the delay', narration: 'Without the dashed delay line the diagram looks like simultaneous exchange \u2014 the delay is what makes it a sequential decision process rather than a single function evaluation.', state: { phase: 'advance', timeShift: false } }
];
var curStep = 0;

function applyStep(i) {
  curStep = (i + steps.length) % steps.length;
  var s = steps[curStep];
  document.getElementById('phaseInput').value = s.state.phase;
  document.getElementById('timeShiftInput').checked = s.state.timeShift;
  state.phase = s.state.phase;
  state.timeShift = s.state.timeShift;
  state.focus = null;
  render();
  document.getElementById('demoNarration').innerHTML =
    '<strong>' + s.title + '</strong><br>' + s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + steps.length;
}
function nextStep() { stopPlay(); applyStep(curStep + 1); }
function prevStep() { stopPlay(); applyStep(curStep - 1); }

